-- Generated by drizzle-kit, then edited by hand for what Drizzle cannot emit: STRICT on every table, the triggers that
-- make access_event append-only, and the one that lets a setup link be redeemed once. Drizzle's snapshot knows none of
-- them, so a later rebuild of these tables drops them; src/features/access/infrastructure/access-schema.test.ts fails.
CREATE TABLE `access_event` (
	`id` text PRIMARY KEY,
	`occurred_at` integer NOT NULL,
	`kind` text NOT NULL,
	`account_id` text,
	`actor_id` text,
	`session_id` text,
	`passkey_id` text,
	`ip` text,
	`device_label` text NOT NULL,
	`detail` text,
	CONSTRAINT `fk_access_event_account_id_account_id_fk` FOREIGN KEY (`account_id`) REFERENCES `account`(`id`),
	CONSTRAINT `fk_access_event_actor_id_account_id_fk` FOREIGN KEY (`actor_id`) REFERENCES `account`(`id`),
	CONSTRAINT "access_event_kind_known" CHECK("kind" in ('account_created', 'setup_link_issued', 'setup_link_redeemed', 'setup_link_refused', 'session_opened', 'session_ended', 'other_sessions_ended', 'sessions_revoked', 'passkey_added', 'passkey_removed', 'sign_in_failed', 'password_set', 'password_changed', 'password_locked', 'username_changed', 'display_name_changed', 'rate_limited')),
	CONSTRAINT "access_event_detail_object" CHECK("detail" is null or (json_valid("detail") and json_type("detail") = 'object'))
) STRICT;
--> statement-breakpoint
CREATE TABLE `account` (
	`id` text PRIMARY KEY,
	`username` text NOT NULL UNIQUE,
	`display_name` text NOT NULL,
	`webauthn_user_handle` text NOT NULL UNIQUE,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	CONSTRAINT "account_username_format" CHECK(length("username") between 3 and 32 and "username" not glob '*[^a-z0-9._-]*'),
	CONSTRAINT "account_display_name_present" CHECK(length(trim("display_name")) between 1 and 60),
	CONSTRAINT "account_user_handle_length" CHECK(length("webauthn_user_handle") = 43)
) STRICT;
--> statement-breakpoint
CREATE TABLE `ceremony` (
	`id` text PRIMARY KEY,
	`kind` text NOT NULL,
	`binding_hash` text NOT NULL,
	`account_id` text,
	`setup_link_id` text,
	`created_at` integer NOT NULL,
	`expires_at` integer NOT NULL,
	CONSTRAINT `fk_ceremony_account_id_account_id_fk` FOREIGN KEY (`account_id`) REFERENCES `account`(`id`),
	CONSTRAINT `fk_ceremony_setup_link_id_setup_link_id_fk` FOREIGN KEY (`setup_link_id`) REFERENCES `setup_link`(`id`),
	CONSTRAINT "ceremony_kind_known" CHECK("kind" in ('setup', 'passkey_registration', 'passkey_sign_in', 'password_sign_in', 'password_change')),
	CONSTRAINT "ceremony_binding_hash_length" CHECK(length("binding_hash") = 43),
	CONSTRAINT "ceremony_setup_names_its_link" CHECK("kind" <> 'setup' or "setup_link_id" is not null),
	CONSTRAINT "ceremony_expires_after_creation" CHECK("expires_at" > "created_at")
) STRICT;
--> statement-breakpoint
CREATE TABLE `passkey` (
	`id` text PRIMARY KEY,
	`account_id` text NOT NULL,
	`credential_id` text NOT NULL UNIQUE,
	`public_key` text NOT NULL,
	`algorithm` integer NOT NULL,
	`sign_count` integer NOT NULL,
	`transports` text NOT NULL,
	`aaguid` text NOT NULL,
	`backup_eligible` integer NOT NULL,
	`backed_up` integer NOT NULL,
	`name` text NOT NULL,
	`created_at` integer NOT NULL,
	`last_used_at` integer,
	CONSTRAINT `fk_passkey_account_id_account_id_fk` FOREIGN KEY (`account_id`) REFERENCES `account`(`id`),
	CONSTRAINT "passkey_algorithm_offered" CHECK("algorithm" in (-7, -8, -257)),
	CONSTRAINT "passkey_sign_count_not_negative" CHECK("sign_count" >= 0),
	CONSTRAINT "passkey_transports_array" CHECK(json_valid("transports") and json_type("transports") = 'array'),
	CONSTRAINT "passkey_backup_flags" CHECK("backup_eligible" in (0, 1) and "backed_up" in (0, 1))
) STRICT;
--> statement-breakpoint
CREATE TABLE `rate_limit` (
	`key` text NOT NULL,
	`window_start` integer NOT NULL,
	`hits` integer NOT NULL,
	CONSTRAINT `rate_limit_pk` PRIMARY KEY(`key`, `window_start`),
	CONSTRAINT "rate_limit_hits_positive" CHECK("hits" > 0)
) STRICT;
--> statement-breakpoint
CREATE TABLE `session` (
	`id` text PRIMARY KEY,
	`account_id` text NOT NULL,
	`verifier` text NOT NULL,
	`method` text NOT NULL,
	`passkey_id` text,
	`authenticated_at` integer NOT NULL,
	`expires_at` integer NOT NULL,
	`last_seen_at` integer NOT NULL,
	`device_label` text NOT NULL,
	CONSTRAINT `fk_session_account_id_account_id_fk` FOREIGN KEY (`account_id`) REFERENCES `account`(`id`),
	CONSTRAINT `fk_session_passkey_id_passkey_id_fk` FOREIGN KEY (`passkey_id`) REFERENCES `passkey`(`id`) ON DELETE SET NULL,
	CONSTRAINT "session_method_known" CHECK("method" in ('passkey', 'password')),
	CONSTRAINT "session_verifier_length" CHECK(length("verifier") = 43),
	CONSTRAINT "session_password_names_no_passkey" CHECK("method" = 'passkey' or "passkey_id" is null),
	CONSTRAINT "session_ends_after_it_starts" CHECK("expires_at" > "authenticated_at"),
	CONSTRAINT "session_device_label_present" CHECK(length(trim("device_label")) between 1 and 100)
) STRICT;
--> statement-breakpoint
CREATE TABLE `setup_link` (
	`id` text PRIMARY KEY,
	`purpose` text NOT NULL,
	`account_id` text,
	`created_by` text,
	`token_hash` text NOT NULL UNIQUE,
	`created_at` integer NOT NULL,
	`expires_at` integer NOT NULL,
	`redeemed_at` integer,
	CONSTRAINT `fk_setup_link_account_id_account_id_fk` FOREIGN KEY (`account_id`) REFERENCES `account`(`id`),
	CONSTRAINT `fk_setup_link_created_by_account_id_fk` FOREIGN KEY (`created_by`) REFERENCES `account`(`id`),
	CONSTRAINT "setup_link_purpose_known" CHECK("purpose" in ('first_setup', 'invite', 'recovery')),
	CONSTRAINT "setup_link_token_hash_length" CHECK(length("token_hash") = 43),
	CONSTRAINT "setup_link_account_by_purpose" CHECK(("purpose" = 'invite' and ("account_id" is null or "redeemed_at" is not null)) or ("purpose" <> 'invite' and "account_id" is not null)),
	CONSTRAINT "setup_link_author_by_purpose" CHECK(("purpose" <> 'first_setup' or "created_by" is null) and ("purpose" <> 'invite' or "created_by" is not null)),
	CONSTRAINT "setup_link_expires_after_creation" CHECK("expires_at" > "created_at")
) STRICT;
--> statement-breakpoint
CREATE INDEX `access_event_by_account` ON `access_event` (`account_id`,`occurred_at`);--> statement-breakpoint
CREATE INDEX `passkey_by_account` ON `passkey` (`account_id`);--> statement-breakpoint
CREATE INDEX `session_by_account` ON `session` (`account_id`);
--> statement-breakpoint
CREATE TRIGGER `access_event_no_update` BEFORE UPDATE ON `access_event`
BEGIN
	SELECT RAISE(ABORT, 'access_event is append-only');
END;
--> statement-breakpoint
CREATE TRIGGER `access_event_no_delete` BEFORE DELETE ON `access_event`
BEGIN
	SELECT RAISE(ABORT, 'access_event is append-only');
END;
--> statement-breakpoint
CREATE TRIGGER `setup_link_redeemed_once` BEFORE UPDATE ON `setup_link` WHEN OLD.`redeemed_at` IS NOT NULL
BEGIN
	SELECT RAISE(ABORT, 'setup_link is redeemed once');
END;